def solve(intervals):
    if not intervals:
        return []
    # sort by start
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0][:]]
    for start, end in intervals[1:]:
        last = merged[-1]
        if start <= last[1]:  # overlap or touch
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    tokens: list of strings, each either an integer literal or an operator '+', '-', '*', '/'.
    Returns the integer result, with division truncated toward zero.
    """
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[-1] if stack else 0

