def solve(nums):
    # Find the pivot: first index from the right where nums[i] < nums[i+1]
    n = len(nums)
    if n <= 1:
        return nums[:]
    i = n - 2
    while i >= 0 and nums[i] >= nums[i+1]:
        i -= 1
    if i == -1:
        return sorted(nums)
    # Find the smallest element greater than nums[i] to the right
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    # Swap
    nums2 = nums[:]
    nums2[i], nums2[j] = nums2[j], nums2[i]
    # Reverse suffix
    nums2[i+1:] = reversed(nums2[i+1:])
    return nums2

