{"task_id": "T37", "code": "def solve(nums):
    n = len(nums)
    if n <= 1:
        return nums[:]
    # find pivot
    i = n - 2
    while i >= 0 and nums[i] >= nums[i+1]:
        i -= 1
    if i == -1:
        return sorted(nums)
    # find rightmost successor
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    # swap and reverse suffix
    result = nums[:]
    result[i], result[j] = result[j], result[i]
    result[i+1:] = reversed(result[i+1:])
    return result
"}

